def state_edges(state: dict) -> tuple[list[int], dict[int, set[int]]]:
    numbers = sorted(int(key) for key in state.get("issues", {}))
    deps: dict[int, set[int]] = {}
    for number in numbers:
        raw = state["issues"][str(number)].get("deps") or []
