package inventory

import (
	"slices"
	"strconv"
	"testing"
)

func TestLowStockReportFormatAndOrder(t *testing.T) {
	t.Chdir(t.TempDir())

	stock := map[string]int{"b": 2, "a": 2, "c": 1, "e": 50}
	want := []string{"c=1", "a=2", "b=2"}
	got := LowStockReport(stock)
	if !slices.Equal(got, want) {
		t.Fatalf("LowStockReport = %v, 期望 %v", got, want)
	}

	// 逐项核对与 LowStockWarehouses 的顺序一致。
	warehouses := LowStockWarehouses(stock)
	if len(got) != len(warehouses) {
		t.Fatalf("长度不一致: LowStockWarehouses=%v, LowStockReport=%v", warehouses, got)
	}
	for i, warehouse := range warehouses {
		wantEntry := warehouse + "=" + strconv.Itoa(stock[warehouse])
		if got[i] != wantEntry {
			t.Fatalf("第 %d 项 %q 与 LowStockWarehouses[%d]=%q 的顺序不一致", i, got[i], i, warehouse)
		}
	}
}

func TestLowStockReportNoLowStock(t *testing.T) {
	t.Chdir(t.TempDir())

	if got := LowStockReport(map[string]int{"a": 50}); len(got) != 0 {
		t.Fatalf("没有低库存时应为空，得到 %v", got)
	}
}
